Hello, I want to classify the IP type os a given ip. I have come around with this code
# Function to classify an IP address based on its type
if ip_cidr_contains("10.0.0.0/8", .ip) ||
   ip_cidr_contains("172.16.0.0/12", .ip) ||
   ip_cidr_contains("192.168.0.0/16", .ip) {
    .ip_type = "private"
} else if ip_cidr_contains("127.0.0.0/8", .ip) {
    .ip_type = "loopback"
} else if ip_cidr_contains("169.254.0.0/16", .ip) {
    .ip_type = "link_local"
} else if ip_cidr_contains("224.0.0.0/4", .ip) {
    .ip_type = "multicast"
} else if ip_cidr_contains("100.64.0.0/10", .ip) {
    .ip_type = "carrier_nat"
} else if ip_cidr_contains("192.0.0.0/24", .ip) ||
          ip_cidr_contains("192.0.2.0/24", .ip) ||
          ip_cidr_contains("198.51.100.0/24", .ip) ||
          ip_cidr_contains("203.0.113.0/24", .ip) {
    .ip_type = "documentation"
} else if ip_cidr_contains("240.0.0.0/4", .ip) {
    .ip_type = "reserved"
} else {
    .ip_type = "public"
}

it works fine, but i dont like so many if. I dont think that is very optimal. Is there a better way to do it?

